import '../models/domain.dart';

/// One bullet / pellet of the built-in library (owner, 2026-10-10).
class LibraryBullet {
  final String brand, name, item;
  /// Kalibre list value (mm) and true diameter (mm).
  final double caliberMm, diameterMm;
  final double grain;
  final double? g1, g7;
  /// The BC the form fills in, with its drag law.
  final BallisticModel model;
  final double bc;
  /// Optional speed bands: (threshold fps, BC below it).
  final List<(int, double)> bands;
  final double? lengthMm;
  final AmmunitionType type;
  final WeaponPlatform platform;
  final String sourceUrl;
  const LibraryBullet(this.brand, this.name, this.item, this.caliberMm, this.diameterMm, this.grain, this.g1, this.g7, this.model, this.bc, this.bands, this.lengthMm, this.type, this.platform, this.sourceUrl);

  /// List text, e.g. "Hornady 6.5mm 140 gr ELD Match".
  String get title => name.toLowerCase().startsWith(brand.toLowerCase()) ? name : '$brand $name';
}

